from rdkit import Chem

def solve(smiles):
    mol = Chem.MolFromSmiles(smiles)
    if mol is None:
        return set()
    donors = set()
    for atom in mol.GetAtoms():
        if atom.GetAtomicNum() in (7, 8, 9):  # N, O, F
            # Check if atom has at least one hydrogen neighbor
            # In RDKit, implicit hydrogens are counted via GetTotalNumHs
            if atom.GetTotalNumHs() > 0:
                donors.add(atom.GetIdx())
    return donors

