using System;
using System.Globalization;

public class ValueComparer
{
    public object Compare(object value1, object value2)
    {
        double num1 = ConvertToDouble(value1);
        double num2 = ConvertToDouble(value2);

        if (num1 > num2)
            return value1;
        else if (num2 > num1)
            return value2;
        else
            return "None";
    }

    private double ConvertToDouble(object value)
    {
        if (value is int intVal)
            return (double)intVal;
        if (value is long longVal)
            return (double)longVal;
        if (value is float floatVal)
            return (double)floatVal;
        if (value is double doubleVal)
            return doubleVal;
        if (value is decimal decimalVal)
            return (double)decimalVal;
        if (value is string strVal)
        {
            // Replace comma with dot for parsing
            strVal = strVal.Replace(',', '.');
            if (double.TryParse(strVal, NumberStyles.Any, CultureInfo.InvariantCulture, out double result))
                return result;
            else
                throw new ArgumentException($"Cannot convert '{value}' to double.");
        }
        throw new ArgumentException($"Unsupported type: {value.GetType()}");
    }
}


public class ValueComparerTest  
