def time_series_cv_split(data, n_splits):
    n = len(data)
    if n_splits <= 0 or n_splits >= n:
        raise ValueError("n_splits must be between 1 and len(data)-1")

    # Determine test size for each split (approximately equal)
    test_size = n // (n_splits + 1)
    if test_size == 0:
        raise ValueError("n_splits too large for data length")

    splits = []
    for i in range(n_splits):
        test_start = (i + 1) * test_size
        if i == n_splits - 1:
            test_end = n
        else:
            test_end = (i + 2) * test_size
        train_indices = list(range(test_start))
        test_indices = list(range(test_start, test_end))
        splits.append((train_indices, test_indices))
    return splits

