#include <cassert>
#include <cmath>

long prime_fib(long n) {
    auto is_prime = [](long long p) -> bool {
        if (p < 2) return false;
        if (p == 2) return true;
        if (p % 2 == 0) return false;
        long long limit = static_cast<long long>(std::sqrt(p)) + 1;
        for (long long k = 3; k <= limit; k += 2) {
            if (p % k == 0) return false;
        }
        return true;
    };
    long long a = 0, b = 1;
    long count = 0;
    while (true) {
        long long c = a + b;
        a = b;
        b = c;
        if (is_prime(c)) {
            count++;
            if (count == n) {
                return static_cast<long>(c);
            }
        }
    }
}

