        auto it = shard.map.find(key);
        if (it != shard.map.end()) {
            if (!update_if_exist) {
                return false; // key exists and we are not allowed to update
            }
            // Update existing entry
            CacheEntry& entry = it->second;
            entry.value = std::move(value);
            entry.size = kv_size;
            // Set expiration: for simplicity, we set a fixed TTL of 3600 seconds
            entry.expire_ts = static_cast<uint32_t>(time(nullptr)) + 3600;
            entry.lease_ttl_on_touch = lease_ttl_on_touch;
            return true;
        } else {
            // Insert new entry
            CacheEntry entry;
            entry.value = std::move(value);
            entry.size = kv_size;
            entry.expire_ts = static_cast<uint32_t>(time(nullptr)) + 3600;
            entry.lease_ttl_on_touch = lease_ttl_on_touch;
            shard.map.insert({key, std::move(entry)});
            return true;
        }
    }

private:
    size_t shard_num_;
    std::vector<Shard<Key, Value, HashFunc, EqualFunc, Map>> shards_;
    HashFunc hash_;
