// Shard containing a map and a mutex
template<typename Key, typename Value, typename HashFunc, typename EqualFunc, typename Map>
class Shard {
public:
    mutable std::shared_mutex mutex;
    Map map;
    HashFunc hash;
    EqualFunc equal;

    Shard() = default;
