// Main cache class
template<typename Key, typename Value, 
         typename HashFunc = DefaultHash, 
         typename EqualFunc = DefaultEqual,
         typename Map = std::unordered_map<Key, CacheEntry, HashFunc, EqualFunc>>
class TtlShardCache {
public:
    static constexpr size_t kDefaultShardNum = 16;

    explicit TtlShardCache(size_t shard_num = kDefaultShardNum)
        : shard_num_(shard_num), shards_(shard_num) {}

    // Load a value by key. Returns true if found and not expired.
    bool Load(const Key& key, Value* value, uint32_t cur_ts = static_cast<uint32_t>(time(nullptr))) {
        size_t shard_idx = hash_(key) % shard_num_;
        auto& shard = shards_[shard_idx];
        std::shared_lock lock(shard.mutex);
        auto it = shard.map.find(key);
        if (it == shard.map.end()) {
            return false;
        }
        CacheEntry& entry = it->second;
        // Check expiration
        if (cur_ts >= entry.expire_ts) {
            // Expired, treat as not found
            return false;
        }
        // Copy value (assuming Value is copyable)
        *value = entry.value; // In real code, we need to convert from stored type to Value
        // If lease_ttl_on_touch is true, extend TTL (not implemented here for simplicity)
        return true;
    }

    // Store a key-value pair
    bool Store(const Key& key, Value&& value, int64_t kv_size, bool lease_ttl_on_touch, bool force, bool update_if_exist) {
        size_t shard_idx = hash_(key) % shard_num_;
        auto& shard = shards_[shard_idx];
        std::unique_lock lock(shard.mutex);
        auto it = shard.map.find(key);
        if (it != shard.map.end()) {
            if (!update_if_exist) {
                return false; // key exists and we are not allowed to update
            }
            // Update existing entry
            CacheEntry& entry = it->second;
            entry.value = std::move(value);
            entry.size = kv_size;
            // Set expiration: for simplicity, we set a fixed TTL of 3600 seconds
            entry.expire_ts = static_cast<uint32_t>(time(nullptr)) + 3600;
            entry.lease_ttl_on_touch = lease_ttl_on_touch;
            return true;
        } else {
            // Insert new entry
            CacheEntry entry;
            entry.value = std::move(value);
            entry.size = kv_size;
            entry.expire_ts = static_cast<uint32_t>(time(nullptr)) + 3600;
            entry.lease_ttl_on_touch = lease_ttl_on_touch;
            shard.map.insert({key, std::move(entry)});
            return true;
        }
