from rdkit import Chem
from rdkit.Chem import rdMolDescriptors

def solve(smiles):
    mol = Chem.MolFromSmiles(smiles)
    if mol is None:
        return set()
    # Get rotatable bonds as a query
    rot_bond_smarts = rdMolDescriptors.RotatableBondSmarts()
    rot_bond_matches = mol.GetSubstructMatches(rot_bond_smarts)
    # Each match is a tuple of atom indices (a1, a2) for the bond
    bond_indices = []
    for a1, a2 in rot_bond_matches:
        bond = mol.GetBondBetweenAtoms(a1, a2)
        if bond is not None:
            bond_indices.append(bond.GetIdx())
    if not bond_indices:
        # No rotatable bonds, return the molecule itself
        return {Chem.MolToSmiles(mol)}
    # Fragment on those bonds
    frag_mol = Chem.FragmentOnBonds(mol, bond_indices, addDummies=False)
    # Get fragments as separate molecules
    frags = Chem.GetMolFrags(frag_mol, asMols=True, sanitizeFrags=False)
    # Canonicalize SMILES
    frag_smiles = set()
    for frag in frags:
        try:
            Chem.SanitizeMol(frag)
        except:
