from rdkit import Chem

def solve(core, chains):
    core_mol = Chem.MolFromSmiles(core)
    if core_mol is None:
        raise ValueError("Invalid core SMILES")
    # Get the dummy atom query
    query = Chem.MolFromSmarts('[#0]')
    # Replace each chain one by one
    current_mol = core_mol
    for chain in chains:
        chain_mol = Chem.MolFromSmiles(chain)
        if chain_mol is None:
            raise ValueError(f"Invalid chain SMILES: {chain}")
        # Replace the first dummy atom with the chain
        res = Chem.ReplaceSubstructs(current_mol, query, chain_mol, replaceAll=False)
        if len(res) == 0:
            raise ValueError("No dummy atom found to replace")
        current_mol = res[0]
    # Sanitize the final molecule
    Chem.SanitizeMol(current_mol)
    smiles = Chem.MolToSmiles(current_mol)
    return {smiles}

