from rdkit import Chem

def solve(smiles):
    mol = Chem.MolFromSmiles(smiles)
    if mol is None:
        return []
    ri = mol.GetRingInfo()
    rings = ri.AtomRings()
    ring_smiles = []
    for ring_atoms in rings:
        # Create a new molecule from the ring atoms and bonds
        # We need to map old atom indices to new indices
        # Build a new RWMol
        new_mol = Chem.RWMol()
        atom_map = {}
        for idx in ring_atoms:
            atom = mol.GetAtomWithIdx(idx)
            new_atom = Chem.Atom(atom.GetAtomicNum())
            new_mol.AddAtom(new_atom)
            atom_map[idx] = new_mol.GetNumAtoms() - 1
        # Add bonds between ring atoms
        for bond in mol.GetBonds():
            i = bond.GetBeginAtomIdx()
            j = bond.GetEndAtomIdx()
            if i in atom_map and j in atom_map:
                new_mol.AddBond(atom_map[i], atom_map[j], bond.GetBondType())
        # Sanitize the new molecule
        try:
            Chem.SanitizeMol(new_mol)
        except:
            pass
        # Get SMILES
        ring_smi = Chem.MolToSmiles(new_mol)
        ring_smiles.append(ring_smi)
    return ring_smiles

