class Solution(object):
    def incremovableSubarrayCount(self, nums):
        n = len(nums)
        count = 0
        for l in range(n):
            for r in range(l, n):
                # check if removing [l, r] leaves strictly increasing
                valid = True
                prev = -1
                # prefix before l
                for i in range(l):
                    if nums[i] <= prev:
                        valid = False
                        break
                    prev = nums[i]
                if not valid:
                    continue
                # suffix after r
                for i in range(r+1, n):
                    if nums[i] <= prev:
                        valid = False
                        break
                    prev = nums[i]
                if valid:
                    count += 1
        return count

