from rdkit import Chem
from rdkit.Chem import ChemicalFeatures
from rdkit import RDConfig
import os

def solve(smiles):
    mol = Chem.MolFromSmiles(smiles)
    if mol is None:
        return 0
    # Load default feature factory
    fdefName = os.path.join(RDConfig.RDDataDir, 'BaseFeatures.fdef')
    factory = ChemicalFeatures.BuildFeatureFactory(fdefName)
    feats = factory.GetFeaturesForMol(mol)
    donors = []
    acceptors = []
    for feat in feats:
        if feat.GetFamily() == 'Donor':
            # Get the atom id (assuming single atom feature)
            atoms = feat.GetAtomIds()
            if atoms:
                donors.append(atoms[0])
        elif feat.GetFamily() == 'Acceptor':
            atoms = feat.GetAtomIds()
            if atoms:
                acceptors.append(atoms[0])
    count = 0
    for d in donors:
        for a in acceptors:
            if d == a:
                continue
            try:
                path = Chem.GetShortestPath(mol, d, a)
                bond_count = len(path) - 1
                if bond_count == 4 or bond_count == 5:
                    count += 1
            except:
                pass
    return count

def check(solve):
    assert solve('CC(O)C(\C)=C/c1cc(ccn1)-c1cc(C)ccc1N') == 1
    assert solve('CC(=O)OC(C(C)N)C(C)CO') == 2


