import heapq

def shortest_path(graph, s, t):
    n = len(graph)
    dist = [float('inf')] * n
    dist[s] = 0
    pq = [(0, s)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        if u == t:
            return d
        for v in range(n):
            w = graph[u][v]
            if w != -1:
                nd = d + w
                if nd < dist[v]:
                    dist[v] = nd
                    heapq.heappush(pq, (nd, v))
    return -1

def check(shortest_path):
    assert shortest_path([[0, 1, 2, -1], [1, 0, 3, -1], [2, 3, 0, 1], [-1, -1, 1, 0]], 0, 3) == 3
    assert shortest_path([[0, 1, 2, -1], [1, 0, 3, -1], [2, 3, 0, 1], [-1, -1, 1, 0]], 0, 1) == 1
    assert shortest_path([[0, 1, 2, -1], [1, 0, 3, -1], [2, 3, 0, 1], [-1, -1, 1, 0]], 0, 2) == 2

