from collections import Counter

class Solution(object):
    def minGroupsForValidAssignment(self, nums):
        freq = Counter(nums)
        n = len(nums)
        low, high = 1, n
        while low < high:
            mid = (low + high) // 2
            if self.is_feasible(mid, n, freq):
                high = mid
            else:
                low = mid + 1
        return low

    def is_feasible(self, g, n, freq):
        x = n // g
        total_min = 0
        total_max = 0
        for f in freq.values():
            min_g = (f + x) // (x + 1)  # ceil(f/(x+1))
            max_g = f // x
            if min_g > max_g:
                return False
            total_min += min_g
            total_max += max_g
        return total_min <= g <= total_max

