from rdkit import Chem
from rdkit.Chem import AllChem

def solve(smiles: str):
    mol = Chem.MolFromSmiles(smiles)
    if mol is None:
        return set()
    # Get rotatable bond smarts pattern
    rot_bond_smarts = Chem.MolFromSmarts('[!$([NH]!@C(=O))&!D1]-&!@[!$([NH]!@C(=O))&!D1]')
    rot_bonds = mol.GetSubstructMatches(rot_bond_smarts)
    # Get bond indices for rotatable bonds
    bond_indices = []
    for (a1, a2) in rot_bonds:
        bond = mol.GetBondBetweenAtoms(a1, a2)
        if bond is not None:
            bond_indices.append(bond.GetIdx())
    if not bond_indices:
        # No rotatable bonds, return original molecule as single fragment
        return {Chem.MolToSmiles(mol, canonical=True)}
    # Fragment molecule by removing those bonds
    frags_mol = AllChem.FragmentOnBonds(mol, bond_indices, addDummies=False)
    # Get fragments as individual molecules
    fragments = Chem.GetMolFrags(frags_mol, asMols=True)
    # Canonicalize SMILES
    frag_smiles = set()
    for frag in fragments:
        frag_smiles.add(Chem.MolToSmiles(frag, canonical=True))
    return frag_smiles

def check(solve):
    assert solve('Nc1cc(-c2cccc3c2CCC3)c(C(=O)O)cc1C1CCCC1') == {'[13*]C(=O)O', '[18*]C1CCCC1', '[3*]c1cccc2c1CCC2', '[4*]c1cc(N)c([19*])cc1[14*]'}
    assert solve('CC(c1ccccc1)C1CCCC1') == {'[1*]C1CCCC1', '[1*]c1ccccc1', '[2*]C([8*])C'}
    assert solve('CC/C(C)=C1/CCC(N(C)c2ccc(C)cc2)C1') == {'[1*]/C(C)=C1/CCC([8*])C1', '[2*]CC', '[7*]N([10*])C', '[8*]c1ccc(C)cc1'}

check(solve)

