class Solution(object):
    def shortestBeautifulSubstring(self, s, k):
        n = len(s)
        best_len = float('inf')
        best_str = ""
        for i in range(n):
            ones = 0
            for j in range(i, n):
                if s[j] == '1':
                    ones += 1
                if ones > k:
                    break
                if ones == k:
                    length = j - i + 1
                    sub = s[i:j+1]
                    if length < best_len:
                        best_len = length
                        best_str = sub
                    elif length == best_len and sub < best_str:
                        best_str = sub
        return best_str

