from collections import defaultdict

def get_most_active_users(json_data, number):
    scores = defaultdict(float)
    for post in json_data:
        author = post['author']
        scores[author] += 1  # post
        scores[author] += 0.1 * len(post['likes'])
        scores[author] += 0.5 * len(post['comments'])
    # Sort by score descending, then by user ID ascending
    sorted_users = sorted(scores.items(), key=lambda x: (-x[1], x[0]))
    return [user for user, _ in sorted_users[:number]]

