#include <vector>
#include <string>
using namespace std;

class Solution {
public:
    long long minimumCost(string source, string target, vector<char> original, vector<char> changed, vector<int> cost) {
        const long long INF = 1e18;
        vector<vector<long long>> dist(26, vector<long long>(26, INF));
        for (int i = 0; i < 26; ++i) dist[i][i] = 0;

        int m = original.size();
        for (int i = 0; i < m; ++i) {
            int u = original[i] - 'a';
            int v = changed[i] - 'a';
            long long c = cost[i];
            if (c < dist[u][v]) dist[u][v] = c;
        }

        // Floyd-Warshall
        for (int k = 0; k < 26; ++k) {
            for (int i = 0; i < 26; ++i) {
                for (int j = 0; j < 26; ++j) {
                    if (dist[i][k] < INF && dist[k][j] < INF) {
                        if (dist[i][k] + dist[k][j] < dist[i][j]) {
                            dist[i][j] = dist[i][k] + dist[k][j];
                        }
                    }
                }
            }
        }

        long long ans = 0;
        int n = source.size();
        for (int i = 0; i < n; ++i) {
            if (source[i] == target[i]) continue;
            int u = source[i] - 'a';
            int v = target[i] - 'a';
            if (dist[u][v] >= INF/2) return -1;
            ans += dist[u][v];
        }
        return ans;
    }
};


