class Solution {
public:
    int numberOfGoodPartitions(vector<int> nums) {
        const int MOD = 1e9 + 7;
        int n = nums.size();
        unordered_map<int, int> first, last;
        for (int i = 0; i < n; ++i) {
            int val = nums[i];
            if (first.find(val) == first.end()) {
                first[val] = i;
            }
            last[val] = i;
        }

        vector<pair<int, int>> intervals;
        for (auto& p : first) {
            int val = p.first;
            intervals.emplace_back(first[val], last[val]);
        }

        sort(intervals.begin(), intervals.end());

        int merged = 0;
        int cur_start = intervals[0].first;
        int cur_end = intervals[0].second;
        for (int i = 1; i < intervals.size(); ++i) {
            if (intervals[i].first <= cur_end) {
                cur_end = max(cur_end, intervals[i].second);
            } else {
                merged++;
                cur_start = intervals[i].first;
                cur_end = intervals[i].second;
            }
        }
        // merged is number of gaps between merged intervals
        // number of merged intervals = merged + 1
        // answer = 2^merged mod MOD
        long long ans = 1;
        long long base = 2;
        int exp = merged;
        while (exp > 0) {
            if (exp & 1) ans = (ans * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return (int)ans;
    }
};
