class Solution {
public:
    vector<int> beautifulIndices(string s, string a, string b, int k) {
        vector<int> a_pos, b_pos;
        int n = s.size();
        int alen = a.size(), blen = b.size();
        // find all occurrences of a
        for (int i = 0; i <= n - alen; ++i) {
            if (s.substr(i, alen) == a) {
                a_pos.push_back(i);
            }
        }
        // find all occurrences of b
        for (int i = 0; i <= n - blen; ++i) {
            if (s.substr(i, blen) == b) {
                b_pos.push_back(i);
            }
        }
        vector<int> result;
        // for each a index, check if any b index within k
        for (int i : a_pos) {
            // binary search for first b index >= i - k
            auto it = lower_bound(b_pos.begin(), b_pos.end(), i - k);
            if (it != b_pos.end() && *it <= i + k) {
                result.push_back(i);
            }
        }
        return result;
    }
};
