template<typename T>
class StlAlloc {
public:
    using value_type = T;

    StlAlloc(std::atomic<int64_t>* alloc_record = nullptr) noexcept
        : record_(alloc_record) {}

    template<typename U>
    StlAlloc(const StlAlloc<U>& other) noexcept
        : record_(other.record_) {}

    T* allocate(std::size_t n) {
        if (n == 0) return nullptr;
        if (n > std::size_t(-1) / sizeof(T))
            throw std::bad_array_new_length();
        void* p = ::operator new(n * sizeof(T));
        if (record_) {
            record_->fetch_add(n * sizeof(T), std::memory_order_relaxed);
        }
        return static_cast<T*>(p);
    }

    void deallocate(T* p, std::size_t n) noexcept {
        if (p) {
            ::operator delete(p);
            if (record_) {
                record_->fetch_sub(n * sizeof(T), std::memory_order_relaxed);
            }
        }
    }

    // Required for allocator equality
    template<typename U>
    bool operator==(const StlAlloc<U>& other) const noexcept {
        return record_ == other.record_;
    }

    template<typename U>
    bool operator!=(const StlAlloc<U>& other) const noexcept {
        return !(*this == other);
    }

private:
    std::atomic<int64_t>* record_;

    template<typename U>
    friend class StlAlloc;
};

// Example usage
int main() {
    std::atomic<int64_t> total_allocated{0};

    {
        std::vector<int, StlAlloc<int>> vec(StlAlloc<int>(&total_allocated));
        vec.push_back(1);
        vec.push_back(2);
        vec.push_back(3);
        std::cout << "Allocated bytes: " << total_allocated.load() << std::endl;
    }

    std::cout << "After deallocation: " << total_allocated.load() << std::endl;
