from math import *
from heapq import *




class Solution:
    def searchRange(self, nums, target):
        def lower_bound(left, right, t):
            while left < right:
                mid = (left + right) // 2
                if nums[mid] < t:
                    left = mid + 1
                else:
                    right = mid
            return left

        l = lower_bound(0, len(nums), target)
        r = lower_bound(0, len(nums), target + 1)

        if l == r:
            return [-1, -1]
        return [l, r - 1]

