import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Random;

public class SongSelector {
    private HashMap<String, List<String>> genreToSongsMap;
    private Random random;

    public SongSelector() {
        genreToSongsMap = new HashMap<>();
        random = new Random();
    }

    public void addSong(String genre, String song) {
        genreToSongsMap.computeIfAbsent(genre, k -> new ArrayList<>()).add(song);
    }

    public String getRandomSongFromGenre(String genre) {
        List<String> songs = genreToSongsMap.get(genre);
        if (songs == null || songs.isEmpty()) {
            return null;
        }
        int index = random.nextInt(songs.size());
        return songs.get(index);
    }
}
