        b = np.array(data['data2'])
        if a.shape != b.shape:
            return jsonify({'error': 'Arrays must have the same length.'}), 400
        result = np.dot(a, b)
        return jsonify({'dot': result.tolist()})
    except Exception as e:
        return jsonify({'error': str(e)}), 400

if __name__ == '__main__':
